#include <cstdint>
#include <cstring>

// Scatter-gather copy engine: reassembles data from a source buffer into
// a destination buffer according to a list of descriptors. Each descriptor
// gives an offset into dst and a length of bytes to pull from src,
// consuming src sequentially across the descriptor list.
//
// NOTE: this variant validates destination bounds using plain 32-bit
// unsigned arithmetic (matching the offsets/lengths parameter width)
// instead of widening to 64-bit before summing.
extern "C" int scatter_gather_copy(
    const unsigned char* src, unsigned int src_len,
    unsigned char* dst, unsigned int dst_len,
    const unsigned int* offsets, const unsigned int* lengths,
    unsigned int desc_count)
{
    if (desc_count == 0) {
        return 0;
    }

    const unsigned int kMaxDescriptors = 64;
    if (desc_count > kMaxDescriptors) {
        return 1;
    }

    const uint64_t src_len64 = static_cast<uint64_t>(src_len);

    // Validation pass: check every descriptor against dst bounds using
    // 32-bit arithmetic (VULNERABLE: offset+length can wrap around when
    // both are large unsigned 32-bit values), and check the cumulative
    // source read position against src bounds using widened arithmetic.
    uint64_t running_src_offset = 0;

    for (unsigned int i = 0; i < desc_count; ++i) {
        const unsigned int dst_off = offsets[i];
        const unsigned int len = lengths[i];

        if (dst_off > dst_len) {
            return 2;
        }
        // VULNERABLE: this addition is performed in 32-bit unsigned
        // arithmetic and can silently wrap around, e.g. 0xFFFFFFF0 + 0x20
        // wraps to 0x10, which can pass this check even though the true
        // 64-bit sum vastly exceeds dst_len.
        const unsigned int dst_end = dst_off + len;
        if (dst_end > dst_len) {
            return 3;
        }

        const uint64_t src_end = running_src_offset + static_cast<uint64_t>(len);
        if (src_end > src_len64) {
            return 4;
        }

        running_src_offset = src_end;
    }

    // All descriptors validated; perform the actual copies.
    uint64_t src_offset = 0;
    for (unsigned int i = 0; i < desc_count; ++i) {
        const unsigned int dst_off = offsets[i];
        const unsigned int len = lengths[i];

        if (len == 0) {
            continue;
        }

        std::memcpy(dst + dst_off, src + src_offset, len);
        src_offset += len;
    }

    return 0;
}

